"""Explain boot range sources, allocation timing and metadata triplets."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1853': ('이미 사용 중인 방에도 점검표가 필요해요. 부팅 때 확보한 메모리 구역을 모아 검사 정보를 준비할 목록에 넣어요.', '초기 검사 대상 세 종류와 주소 변환, 구조체 크기를 이해합니다.', '예약 구간·커널 data·사용 중인 노드의 관리 구조 세 줄을 목록에 적고 기록 함수로 화살표를 보내세요.', ['KMSAN은 데이터와 별도로 준비 상태를 기록하는 shadow, 발생 원인을 기록하는 origin 정보를 사용해요. 부팅은 운영체제를 시작하는 과정이에요. kmsan_init_shadow는 이미 쓰는 메모리 구간에도 이런 검사 정보를 준비하는 초기화 함수예요.', '먼저 예약된 물리 메모리 구간을 순회해요. 물리 주소는 실제 메모리 위치를 나타내고 가상 주소는 커널이 그 위치를 다룰 때 쓰는 주소 체계예요. 시작과 끝을 phys_to_virt로 변환한 뒤 기록 함수에 넘겨요.', '이 변환은 주소를 바꾸어 표현하는 일이에요. 메모리 내용을 사용자 프로그램으로 복사하는 작업이 아니에요. 변환 가능한 예약 구간이라는 부팅 경로의 전제 아래 읽어야 해요.', '다음에는 _sdata부터 _edata까지의 커널 .data 구간을 등록해요. .data는 커널의 데이터가 놓이는 영역 이름이에요. 함수의 설명 주석에 넓은 개요가 있더라도 실제 본문에서 어떤 등록 호출을 하는지 따로 확인해요.', '그다음 online node, 즉 사용 중인 메모리 노드마다 NODE_DATA 구조체의 구간을 등록해요. 노드는 메모리 배치와 접근 특성에 따라 나눈 관리 단위라고 생각하면 돼요. NODE_DATA는 해당 노드의 관리 정보를 담는 구조이며 노드의 모든 메모리 자체와는 달라요.', '이 구조체의 크기 nd_size는 sizeof(pg_data_t)로 구해요. 시작 주소를 char 포인터로 바꾼 뒤 이 바이트 수를 더해 끝 경계를 만들어요. 모형에서 크기를 96이라고 정했더라도 실제 크기가 모든 설정에서 96이라는 뜻은 아니에요. 끝에는 모은 구간 목록을 순회해 검사 정보를 준비해요.'], [('예약된 물리 주소는 구간을 기록하기 전에 어떻게 처리하나요?', ['내용을 언제나 사용자 주소로 복사해요', 'phys_to_virt로 커널이 다룰 가상 주소로 바꿔요'], '정답은 두 번째예요. 시작과 끝 주소를 각각 변환해 기록해요. 주소 표현의 변환과 실제 데이터 복사는 다른 일이에요.'), ('NODE_DATA 관리 구조체의 등록 길이는 무엇으로 구하나요?', ['sizeof(pg_data_t)로 구해요', '어떤 설정에서도 무조건 96바이트로 정해요'], '정답은 첫 번째예요. 실제 형식의 크기를 계산해 사용해요. 학습 모형의 작은 숫자를 모든 컴퓨터의 실제 구조체 크기로 외우면 안 돼요.')]), 'os1854': ('필요한 준비물 목록을 먼저 모은 뒤 목록을 따라 물건을 준비해요. 목록에 한 줄 적는 순간과 실제 물건을 얻는 순간은 달라요.', '구간 수집과 검사 정보 할당의 두 단계, 부팅 시점 조건을 이해합니다.', '구간 모으기→목록 완성→각 구간의 shadow·origin 준비라는 세 칸을 그리세요.', ['kmsan_init_shadow 앞부분은 예약 구간과 커널 데이터 등의 주소를 목록에 기록해요. 기록 함수는 페이지 경계에 맞추고 가능한 첫 기존 구간과 합치거나 새 항목을 추가해요. 목록은 작업 대상의 시작·끝 주소를 담아요.', '마지막 for 반복문은 i가 0부터 future_index보다 작은 동안 한 항목씩 처리해요. future_index는 현재 등록한 항목 수예요. 항목 수가 3이면 0번, 1번, 2번을 방문해요.', '각 항목의 start와 end를 kmsan_init_alloc_meta_for_range에 넘겨요. meta는 데이터를 검사하기 위해 따로 두는 정보라는 뜻이에요. 이 함수에서 실제 shadow와 origin 공간을 준비하므로 기록과 할당의 책임이 나뉘어요.', '이 준비 함수는 memblock_alloc으로 shadow와 origin 공간을 각각 얻고, 대상 페이지와 연결해요. memblock은 부팅 초기 메모리를 관리하는 장치예요. 목록의 구간들을 비교할 때마다 이 할당을 하는 것이 아니에요.', '원문 주석은 이 초기화 작업에서 memblock을 통한 할당은 slab 초기화 전에 해야 한다고 명시해요. slab은 커널이 작은 객체들을 효율적으로 할당하는 방식이에요. 부팅이 진행되면서 쓸 수 있는 관리 기능과 사용 조건이 달라져요.', '따라서 이 초기화 함수를 실행 중 아무 때나 불러도 되는 영구 할당 서비스로 보면 안 돼요. 초기화용 함수와 자료의 수명, 호출 시점을 함께 지켜야 해요. 종이 목록 실습은 처리 순서를 배우는 것이며 실제 부팅 할당기의 전환을 실행하는 실험은 아니에요.'], [('기록한 미래 구간마다 실제 검사 정보 준비 함수를 부르는 반복은 어디에 있나요?', ['기록 함수가 두 구간을 비교할 때마다 있어요', 'init_shadow의 마지막 for 반복에 있어요'], '정답은 두 번째예요. 먼저 목록을 모으고 마지막 반복에서 start와 end를 준비 함수로 넘겨요. 비교 횟수와 실제 준비 호출 횟수는 같은 뜻이 아니에요.'), ('이 초기화 함수의 주석은 memblock 할당 시점을 어떻게 설명하나요?', ['slab 초기화 전이어야 한다고 설명해요', '언제든 영구적으로 같은 방식으로 사용할 수 있다고 설명해요'], '정답은 첫 번째예요. 부팅 단계의 사용 조건을 명시한 주석이에요. 이 경로의 초기화용 할당을 일반 실행 중의 할당과 같은 것으로 보지 마세요.')]), 'os1855': ('같은 크기의 상자 세 개가 오면 두 개는 점검 기록용, 하나는 실제 내용용으로 묶어요. 크기가 다른 상자는 별도 줄에 모아 둬요.', 'order별 보관 칸과 shadow·origin을 먼저 확보하는 원리를 이해합니다.', '같은 order로 A, B, C가 들어오면 A는 shadow, B는 origin, C는 데이터라고 이름을 붙이세요.', ['KMSAN은 데이터 페이지 외에 준비 상태를 담는 shadow와 발생 원인을 담는 origin 페이지를 사용해요. 페이지는 메모리를 일정 크기로 나눈 구역이에요. 부팅 중 이 함수는 데이터와 검사 정보를 위한 묶음을 준비해요.', 'order는 블록에 든 페이지 수를 나타내는 단계예요. order 0은 1페이지, 1은 2페이지, 2는 4페이지처럼 2의 order승 개예요. 블록은 이 페이지들을 한 덩어리로 다루는 단위예요.', 'held_back 배열은 order마다 shadow와 origin을 가리키는 두 자리를 가져요. 포인터는 해당 블록의 위치를 가리키는 값이에요. 두 자리가 비어 있을 때 같은 order의 첫 블록 A가 들어오면 shadow 자리에서 A를 가리키게 하고 false를 반환해요.', '같은 order의 다음 블록 B가 들어오면 shadow는 이미 있으니 비어 있는 origin 자리에 B를 보관하고 false를 반환해요. 이때 false는 두 블록을 일반 페이지로 바로 돌려보내지 않고 KMSAN이 맡아 둔다는 뜻이에요.', '같은 order의 세 번째 블록 C가 들어오면 앞의 A와 B를 C의 검사 정보로 연결할 수 있어요. order별로 보관하므로 크기가 다른 블록이 중간에 들어와도 각 order의 보관 상태를 따로 사용해요.', 'order 1의 2페이지 데이터 블록은 같은 크기의 shadow 블록과 origin 블록으로 연결해요. order별 배열이 모든 블록 크기를 같게 만드는 것이 아니라 원래 같은 크기끼리 묶게 하는 거예요. 처리 끝에 한두 블록이 남는 경우는 이후 정리 경로의 별도 대상이에요.'], [('보관 칸이 빈 상태에서 같은 order의 첫 두 블록은 어디에 남나요?', ['두 블록 모두 즉시 일반 데이터 페이지로 반환해요', 'shadow와 origin 보관 자리에 각각 남아요'], '정답은 두 번째예요. 첫 if는 shadow를, 다음 호출의 두 번째 if는 origin을 채운 뒤 false를 반환해요. 데이터용 블록을 추적할 검사 공간부터 확보하는 순서예요.'), ('held_back을 order별로 나누는 이유는 무엇인가요?', ['같은 크기의 데이터·검사 정보 블록을 묶으려고요', '서로 다른 크기의 블록을 자동으로 모두 같은 크기로 바꾸려고요'], '정답은 첫 번째예요. order는 페이지 개수를 정하므로 대응하는 크기끼리 연결해야 해요. 배열에서 order를 고르는 것 자체가 블록 크기를 바꾸는 작업은 아니에요.')]), 'os1856': ('세 번째 상자에 앞서 보관한 두 점검표를 연결한 뒤, 보관 목록의 빈자리를 다음 묶음에 내줘요. 목록을 비운다고 점검표 자체를 버리는 것은 아니에요.', '세 번째 블록의 연결, 반환값과 실제 페이지 반환의 책임을 구별합니다.', 'A·B를 검사 정보로 C에 연결→두 보관 포인터 NULL→true→호출자가 페이지 반환 처리라는 순서를 그리세요.', ['같은 order의 shadow와 origin 블록이 이미 held_back에 있으면 새로 들어온 page는 데이터용 블록으로 처리돼요. 함수는 보관한 두 포인터를 지역 변수 shadow와 origin에 먼저 가져와요.', 'kmsan_setup_meta(page, shadow, origin, order)가 세 블록을 연결해요. 실제 도우미는 데이터 블록의 각 페이지에 대응하는 shadow·origin 페이지를 가리키도록 설정해요. 여기서 새 검사 블록 두 개를 다시 할당하는 것은 아니에요.', '연결한 뒤 held_back[order].shadow와 .origin에 NULL을 써요. NULL은 지금 보관한 블록이 없다는 표시예요. 다음 세 블록 묶음을 받을 수 있도록 보관 상태를 비우는 거예요.', '이 NULL 대입이 연결한 검사 정보의 메모리를 해제하거나 데이터와의 연결을 지우지는 않아요. 데이터 페이지의 검사 정보 연결과 임시 보관 배열의 두 포인터는 서로 다른 저장 위치예요.', '함수는 마지막에 true를 반환해요. 이 함수 본문에는 __free_pages_core를 직접 호출하는 줄이 없어요. 호출하는 초기화 경로는 false면 KMSAN이 맡은 페이지라 돌아가고, true면 후속 처리와 실제 페이지 반환 호출을 이어가요.', '따라서 true는 호출자에게 다음 처리를 진행해도 된다는 결과를 알리는 것이에요. 반환값 그 자체가 메모리 반환 동작은 아니에요. A·B·C 처리 뒤 보관 자리가 비면 같은 order의 D는 다시 첫 shadow 블록으로 보관되는 다음 주기가 시작돼요.'], [('세 번째 블록에서 true를 반환하는 것이 이 함수 안에서 직접 페이지를 반환하는 호출인가요?', ['네. 여기서 언제나 __free_pages_core를 직접 불러요', '아니요. 호출자에게 후속 반환 처리를 진행할 수 있다고 알려요'], '정답은 두 번째예요. 본문은 검사 정보 연결과 보관 포인터 정리 후 true를 돌려줘요. 실제 페이지 반환 호출은 이를 받은 호출 경로에서 수행해요.'), ('한 묶음의 세 블록을 처리하면 해당 order의 held_back 포인터 둘은 어떻게 되나요?', ['둘 다 NULL로 비워져 다음 묶음을 받을 수 있어요', '이전 shadow를 언제나 영구 보관해요'], '정답은 첫 번째예요. 데이터 페이지에 연결한 검사 정보는 유지하면서 임시 보관 자리만 비워요. 포인터 칸을 비우는 것과 연결된 메모리를 해제하는 것은 달라요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_459.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
